#!/usr/bin/env bash
set -euo pipefail
ROOT=/work;BUILD="$ROOT/build";TOOL="${MOS_TOOLCHAIN:-$BUILD/llvm-mos-install}/bin";CFG="$BUILD/install/bin/mos-snes.cfg";SRC="$ROOT/examples/snes/modethread.c";VENDOR="$ROOT/vendor/bsnes-jg";A16=(-Xclang -target-feature -Xclang +mos-a16);XY16=(-Xclang -target-feature -Xclang +mos-a16 -Xclang -target-feature -Xclang +mos-xy16)
cc -O2 "$ROOT/tools/modethread-sim.c" -o "$BUILD/modethread-sim";EXPECT=$("$BUILD/modethread-sim"|grep -oE '0x[0-9A-Fa-f]{4}'|head -1);echo "==> host oracle: $EXPECT"
for mode in default a16 xy16;do feat=();[ "$mode" = a16 ]&&feat=("${A16[@]}");[ "$mode" = xy16 ]&&feat=("${XY16[@]}");"$TOOL/mos-clang" --config "$CFG" -mcpu=mosw65816 "${feat[@]}" -Os -mllvm -verify-machineinstrs -Wl,-Map="$BUILD/modethread-$mode.map" -o "$BUILD/modethread-$mode.sfc" "$SRC";python3 "$ROOT/tools/snes-checksum.py" "$BUILD/modethread-$mode.sfc">/dev/null;done
"$TOOL/mos-clang" --target=mos -mcpu=mosw65816 "${A16[@]}" -Os -fno-lto -mllvm -verify-machineinstrs -c "$ROOT/examples/65816/modethread-probe.c" -o "$BUILD/modethread.o";dis=$("$TOOL/llvm-objdump" -dr --mcpu=mosw65816 "$BUILD/modethread.o");printf '%s\n' "$dis"|grep -Eq 'jmp[[:space:]]+\('||{ echo 'FAIL: no indirect jump';exit 1;};printf '%s\n' "$dis"|grep -qw rep;printf '%s\n' "$dis"|grep -qw sep;echo '    PASS: computed goto + mixed width brackets'
rc=0;export SMOKE_SETTLE=480;export SMOKE_SECONDS=12;source "$ROOT/dev/_emu.sh";require_bios||exit $?;for mode in default a16 xy16;do run_assert "$BUILD/modethread-$mode.sfc" "$BUILD/modethread-$mode.map" corpus_result "$EXPECT"||rc=1;VMA=$(awk '$NF=="corpus_result"{print $1;exit}' "$BUILD/modethread-$mode.map");"$BUILD/jgxcheck" "$BUILD/modethread-$mode.sfc" "$VENDOR/Database" "0x$VMA" 2 "$EXPECT" 480 "$BUILD/modethread-$mode-jg.png"||rc=1;done;[ "$rc" = 0 ]&&echo "RESULT: PASS — ModeThread host == default == a16 == xy16 == $EXPECT"||echo 'RESULT: FAIL';exit "$rc"
